create or replace function public.review_listing_report(p_report_id uuid,p_decision text,p_notes text default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_report public.listing_reports%rowtype;v_actor uuid:=auth.uid();v_decision text:=lower(trim(coalesce(p_decision,'')));v_status text;
begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_report from public.listing_reports where id=p_report_id for update;if not found then raise exception 'report_not_found';end if;if not private.has_tenant_role(v_report.tenant_id,array['staff','admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('resolve','dismiss') then raise exception 'invalid_decision';end if;v_status:=case when v_decision='resolve' then 'resolved' else 'dismissed' end;update public.listing_reports set status=v_status,staff_notes=nullif(trim(coalesce(p_notes,'')),''),reviewed_by=v_actor,reviewed_at=now(),updated_at=now() where id=p_report_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_report.tenant_id,v_actor,case when v_decision='resolve' then 'listing_report_resolved' else 'listing_report_dismissed' end,(case when v_decision='resolve' then 'Resolved' else 'Dismissed' end)||' listing report '||p_report_id::text||coalesce(' for business '||v_report.business_id::text,''));return jsonb_build_object('ok',true,'report_id',p_report_id,'decision',v_decision,'status',v_status,'business_id',v_report.business_id);end;$$;
revoke all on function public.review_listing_report(uuid,text,text) from public;grant execute on function public.review_listing_report(uuid,text,text) to authenticated;
